ST.xhtml:
(* ============================================================================ Payload Generation and MQTT Publishing for Yacht Fleet Monitoring ============================================================================ Description: - Generates telemetry payload containing timestamp, sequence number, and metrics - Creates JSON-formatted payloads using two methods (WagoAppJSON and Format9) - Publishes data to MQTT broker for multiple yacht clients
Author: Alexander Fugmann Date: 2025-11-21 Version: 1.0 ============================================================================ *)
oTP1(IN := NOT oTP2.Q, PT := tPublishTime); // Timer 1: ON phasen) xExecute := oTP1.Q; oTP2(IN := NOT oTP1.Q, PT := tPublishTime); // Timer 2: OFF phase // Publish only when client is connected to broker
(* -------------------------------------------------------------------------- SECTION 1: Payload Data Preparation -------------------------------------------------------------------------- *) // Update custom payload structure with current sensor/metric values oFbCustomPayload(xEnable := xEnable);
// Populate parameter value array for JSON template substitution // Note: Array indices 0-8 correspond to #Parameter placeholders in sJSON_BaseFrame sValueArray[0] := LINT_TO_STRING(oFbCustomPayload.typPayloadOut.liTimestamp); // Unix timestamp (ms) sValueArray[1] := INT_TO_STRING(oFbCustomPayload.typPayloadOut.usiSeq); // Sequence number sValueArray[2] := INT_TO_STRING(oFbCustomPayload.typPayloadOut.usiMetricCnt); // Total metric count sValueArray[3] := REAL_TO_STRING(oFbCustomPayload.typPayloadOut.atypMetrics[1].rValue); // Metric 1 value sValueArray[4] := oFbCustomPayload.typPayloadOut.atypMetrics[1].sName; // Metric 1 name sValueArray[5] := REAL_TO_STRING(oFbCustomPayload.typPayloadOut.atypMetrics[2].rValue); // Metric 2 value sValueArray[6] := oFbCustomPayload.typPayloadOut.atypMetrics[2].sName; // Metric 2 name sValueArray[7] := REAL_TO_STRING(oFbCustomPayload.typPayloadOut.atypMetrics[3].rValue); // Metric 3 value sValueArray[8] := oFbCustomPayload.typPayloadOut.atypMetrics[3].sName; // Metric 3 name
(* -------------------------------------------------------------------------- SECTION 2: JSON Payload Generation (Method 1 - WagoAppJSON) -------------------------------------------------------------------------- *) // Trigger JSON writer if no error condition exists IF NOT oFb_JSON_Writer_02.xError THEN xTriggerJSONWriter := TRUE; END_IF
// Generate JSON string by substituting #Parameter placeholders with actual values oFb_JSON_Writer_02( sJSON_BaseFrame := sJSON_BaseFrame, // Template with #Parameter placeholders aParameterValues := sValueArray, // Array of substitution values xTrigger := xTriggerJSONWriter, // Execution trigger sOutput := sPayload_WAGO_JSON // Resulting JSON string );
(* -------------------------------------------------------------------------- SECTION 3: JSON Payload Generation (Method 2 - Format9) -------------------------------------------------------------------------- *) // Alternative method using Format9 for direct JSON string formatting // Format specifiers: %li=LINT, %i=INT, %.2f=REAL (2 decimals), %s=STRING sPayload_FormatX := Format9( sFormat := '{"timestamp":%li,"seq":%i,"MetricCnt":%i,"MetricValue":%.2f,"MetricName":"%s","MetricValue2":%.2f,"MetricName2":"%s","MetricValue3":%.2f,"MetricName3":"%s"}', p1 := ADR(oFbCustomPayload.typPayloadOut.liTimestamp), // Pointer to timestamp p2 := ADR(oFbCustomPayload.typPayloadOut.usiSeq), // Pointer to sequence p3 := ADR(oFbCustomPayload.typPayloadOut.usiMetricCnt), // Pointer to metric count p4 := ADR(oFbCustomPayload.typPayloadOut.atypMetrics[1].rValue), // Pointer to metric 1 value p5 := ADR(oFbCustomPayload.typPayloadOut.atypMetrics[1].sName), // Pointer to metric 1 name p6 := ADR(oFbCustomPayload.typPayloadOut.atypMetrics[2].rValue), // Pointer to metric 2 value p7 := ADR(oFbCustomPayload.typPayloadOut.atypMetrics[2].sName), // Pointer to metric 2 name p8 := ADR(oFbCustomPayload.typPayloadOut.atypMetrics[3].rValue), // Pointer to metric 3 value p9 := ADR(oFbCustomPayload.typPayloadOut.atypMetrics[3].sName) // Pointer to metric 3 name );
(* -------------------------------------------------------------------------- SECTION 4: MQTT Client Management and Publishing -------------------------------------------------------------------------- *) IF xFirstCycle THEN xFirstCycle:=FALSE; FOR index := ciFIRST_INDEX TO ciLAST_INDEX DO
sIndexTopic := Format1(sFormat := 'yachtFleet/%i/data', p1 := ADR(index)); wsTopic := TO_WSTRING(sIndexTopic); // Convert to WSTRING for MQTT library
sIndexTopic2 := Format1(sFormat := 'yachtFleetDetailed/%i/data', p1 := ADR(index)); wsTopic2 := TO_WSTRING(sIndexTopic2); // Convert to WSTRING for MQTT library
// Configure and maintain MQTT client connection aMQTTClient[index]( xEnable := xEnable, // Master enable for client sHostname := sHostname, // MQTT broker hostname/IP uiPort := uiPort, // MQTT broker port (typically 1883) sClientId := CONCAT('YachtClient_', INT_TO_STRING(index)), // Unique client ID xCleanSession := TRUE, // Start with clean session (no persistent state) uiKeepAlive := 60, // Keep-alive interval in seconds xUseTLS := FALSE, // TLS/SSL encryption disabled (set TRUE for production) xWillRetain := FALSE, // Last Will message not retained pbWillMessage := 0, // No Last Will message configured uiWillMessageSize := 0 // Last Will message size ); aMQTTClient2[index]( xEnable := xEnable, // Master enable for client sHostname := sHostname, // MQTT broker hostname/IP uiPort := uiPort, // MQTT broker port (typically 1883) sClientId := CONCAT('YachtClient2_', INT_TO_STRING(index)), // Unique client ID xCleanSession := TRUE, // Start with clean session (no persistent state) uiKeepAlive := 60, // Keep-alive interval in seconds xUseTLS := FALSE, // TLS/SSL encryption disabled (set TRUE for production) xWillRetain := FALSE, // Last Will message not retained pbWillMessage := 0, // No Last Will message configured uiWillMessageSize := 0 // Last Will message size ); END_FOR
END_IF // Iterate through all yacht clients in the fleet FOR index := ciFIRST_INDEX TO ciLAST_INDEX DO
// Generate unique MQTT topic for each yacht: "yachtFleet/<index>/data"
(* ---------------------------------------------------------------------- SECTION 4.1: Publish Logic with Timing Control ---------------------------------------------------------------------- *)
IF aMQTTClient[index].xConnectedToBroker THEN
// Pulse generator for periodic publishing (alternating timers create continuous pulse train)
// Pointer und Länge für den kleineren Payload pbPayloadPtr := ADR(sPayload_WAGO_JSON); udiPayloadLen := WagoSysString.strnlen(p := ADR(sPayload_WAGO_JSON), udiSize := SIZEOF(sPayload_WAGO_JSON));
aMQTTPublish[index]( xExecute := xExecute, udiTimeOut := udiTimeOut, eQoS := MQTT.MQTT_QOS.QoS0, xRetain := FALSE, pbPayload := pbPayloadPtr, udiPayloadSize := udiPayloadLen, mqttClient := aMQTTClient[index], wsTopicName := wsTopic, eMQTTError => );
// Pointer und Länge für das große GVL-Feld //MEMUtils.MemSet(pbyBuffer := ADR(sPayload_WAGO_JSON),byValue := 0,dwSize := SIZEOF(sPayload_WAGO_JSON)); pbPayloadPtr2 := ADR(GVL_Fast.sJSONMetricOutput); udiPayloadLen2 := WagoSysString.strnlen(p := ADR(GVL_Fast.sJSONMetricOutput), udiSize := SIZEOF(GVL_Fast.sJSONMetricOutput));
aMQTTPublishComplex[index]( xExecute := xExecute, udiTimeOut := udiTimeOut, eQoS := MQTT.MQTT_QOS.QoS0, xRetain := FALSE, pbPayload := pbPayloadPtr2, udiPayloadSize := udiPayloadLen2, mqttClient := aMQTTClient2[index], wsTopicName := wsTopic2, eMQTTError => );
END_IF
END_FOR
(* ============================================================================ END OF PUBLISHING ROUTINE ============================================================================ *)

// ============================================
// MQTT Subscribe Function Block
// ============================================
oFbSubscribeMQTT(
    xSubscribe          := xSubscribe, 
    sTopic              := sTopic, 
    eQoS                := eQoS, 
    aPayloadData        := aPayloadData, 
    xBusy               => xBusy, 
    xError              => xError, 
    oStatus             => oStatus, 
    xDataReceived       => xDataReceived, 
    dwRxNBytes          => dwRxNBytes, 
    xDataTruncated      => xDataTruncated, 
    sReceivedTopic      => sReceivedTopic
);


// ============================================
// Process received MQTT data
// ============================================
IF xDataReceived THEN
    // Copy byte array to string using MemCopySecure 
    MemCopySecure(
        pDest           := ADR(sJsonMessage),
        udiDestSize     := SIZEOF(sJsonMessage),
        pSource         := ADR(aPayloadData),
        udiSourceSize   := dwRxNBytes,
        bPadding        := 0
    );

    xDataReceived := FALSE;
    xTriggerParse := TRUE;
    bParseState := 0;
END_IF;

// ============================================
// JSON Parsing State Machine
// ============================================
CASE bParseState OF

    0: // Idle state
        IF xTriggerParse THEN
            bParseState := 1;
            xTriggerParse := TRUE;  // Set trigger for parsing
        END_IF;

    1: // Parse JSON structure
        oJsonParser(
            pData           := ADR(aPayloadData),
            udiSizeData     := dwRxNBytes,
            xTrigger        := xTriggerParse
        );

        // Check if parsing is complete
        IF oJsonParser.xDone THEN
            xTriggerParse := FALSE;  // Reset trigger
            bParseState := 2;  // Move to get timestamp
        ELSIF oJsonParser.xError THEN
            xTriggerParse := FALSE;  // Reset trigger
            bParseState := 0;  // Reset on error
        END_IF;

    2: // Get timestamp
        sJsonPointer := '/timestamp';

        IF NOT xTriggerGetTimestamp THEN
            xTriggerGetTimestamp := TRUE;  // Trigger method once
        END_IF;

        oGetValue := oJsonParser.GetValueByPath(
            sPointer    := sJsonPointer,
            xTrigger    := xTriggerGetTimestamp
        );

        IF oGetValue.eReturn = 0 THEN  // 0 = Values are valid
            IF oGetValue.eType = WagoAppJSON.JSON_NUMBER THEN
                sTimestampValue := oGetValue.sValue;
                liTimestampMs := STRING_TO_LINT(sTimestampValue); //TimeStamp conversation
                udiUnixTimestamp := LINT_TO_UDINT(liTimestampMs / 1000);
                dtLastDetectionUTC := UDINT_TO_DT(udiUnixTimestamp);
				dtLastDetectionCET := UDINT_TO_DT(udiUnixTimestamp+7200);
				dtLastDetectionCEST :=UDINT_TO_DT(udiUnixTimestamp+10800);
            END_IF;
            xTriggerGetTimestamp := FALSE;
            bParseState := 3;  // Move to get class
        ELSIF oGetValue.eReturn < 0 THEN  // <0 = Values invalid (error)
            xTriggerGetTimestamp := FALSE;
            bParseState := 3;  // Continue anyway
        END_IF;

    3: // Get detection class from first detection
        sJsonPointer := '/detections/0/class';

        IF NOT xTriggerGetClass THEN
            xTriggerGetClass := TRUE;  // Trigger method once
        END_IF;

        oGetValue := oJsonParser.GetValueByPath(
            sPointer    := sJsonPointer,
            xTrigger    := xTriggerGetClass
        );

        IF oGetValue.eReturn = 0 THEN  // 0 = Values are valid
            IF oGetValue.eType = WagoAppJSON.JSON_STRING THEN
                sDetectionClass := oGetValue.sValue;
                xTriggerGetClass := FALSE;
                bParseState := 4;  // Move to get confidence
            ELSE
                xTriggerGetClass := FALSE;
                xLowConfidence := TRUE;
                bParseState := 0;
            END_IF;
        ELSIF oGetValue.eReturn < 0 THEN  // <0 = Values invalid (error)
            xTriggerGetClass := FALSE;
            xLowConfidence := TRUE;
            bParseState := 0;
        END_IF;

    4: // Get confidence from first detection
        sJsonPointer := '/detections/0/confidence';

        IF NOT xTriggerGetConfidence THEN
            xTriggerGetConfidence := TRUE;  // Trigger method once
        END_IF;

        oGetValue := oJsonParser.GetValueByPath(
            sPointer    := sJsonPointer,
            xTrigger    := xTriggerGetConfidence
        );

        IF oGetValue.eReturn = 0 THEN  // 0 = Values are valid
            IF oGetValue.eType = WagoAppJSON.JSON_NUMBER THEN
                sConfidenceValue := oGetValue.sValue;
                rConfidence := STRING_TO_REAL(sConfidenceValue);
                xTriggerGetConfidence := FALSE;
                bParseState := 5;  // Move to update state
            ELSE
                xTriggerGetConfidence := FALSE;
                xLowConfidence := TRUE;
                bParseState := 0;
            END_IF;
        ELSIF oGetValue.eReturn < 0 THEN  // <0 = Values invalid (error)
            xTriggerGetConfidence := FALSE;
            xLowConfidence := TRUE;
            bParseState := 0;
        END_IF;

    5: // Update helmet state based on detection
        IF rConfidence >= CONFIDENCE_THRESHOLD THEN
            xLowConfidence := FALSE;

            IF sDetectionClass = 'white helmet' THEN
                bState := eHelmetState.white_helmet;
            ELSIF sDetectionClass = 'blue helmet' THEN
                bState := eHelmetState.blue_helmet;
            ELSIF sDetectionClass = 'head' THEN
                bState := eHelmetState.head;
            ELSE
                bState := eHelmetState.idle;
            END_IF;
        ELSE
            xLowConfidence := TRUE;
        END_IF;

        bParseState := 0;  // Return to idle

ELSE
    bParseState := 0;  // Safety: return to idle
END_CASE;

// ============================================
// LED Control State Machine
// ============================================
IF xLowConfidence or xWrongType THEN
    // Low confidence or error - all LEDs off (default)
    LED_White := FALSE;
    LED_Blue  := FALSE;
    LED_Red   := FALSE;
ELSE
    // Normal operation - control LEDs based on state
    CASE bState OF
        eHelmetState.white_helmet:
            LED_White := TRUE;
            LED_Blue  := FALSE;
            LED_Red   := FALSE;

        eHelmetState.blue_helmet:
            LED_White := FALSE;
            LED_Blue  := TRUE;
            LED_Red   := FALSE;

        eHelmetState.head:
            LED_White := FALSE;
            LED_Blue  := FALSE;
            LED_Red   := TRUE;
    ELSE
        // Default or error handling (idle state)
        LED_White := FALSE;
        LED_Blue  := FALSE;
        LED_Red   := FALSE;
    END_CASE;
END_IF;

GVL.typCurrentTime:=FuGetLocalTimeComponents();
GVL.dtCurrentTime:=FuGetLocalDateAndTime();


ACT_Publish();
ACT_Subscribe();
(*

Erstelle einen weiteren JSON_BaseFrame mit dem namen JSON_BaseFrameBesecke im UNS ISA 95 format für eine Yacht mit 142 sinnvollen Datenpunkten und ein passendes sValueArray							: ARRAY[0..8] OF STRING(JSON_MAX_PARAMETER_STRING);

*)

IF xEnable THEN
(* ---------------------------------------------------------------------- Sequence Counter with Rollover Protection ---------------------------------------------------------------------- *) IF uiSeqCounter >= 255 THEN uiSeqCounter := 0; ELSE uiSeqCounter := uiSeqCounter + 1; END_IF;
(* ---------------------------------------------------------------------- Timestamp Generation (milliseconds since system start) ---------------------------------------------------------------------- *) typPayloadOut.liTimestamp := TO_LINT(TIME_TO_LTIME(TIME())); typPayloadOut.usiSeq := TO_USINT(uiSeqCounter);
(* ---------------------------------------------------------------------- Time Base for Waveform Generation ---------------------------------------------------------------------- *) // Convert sequence counter to time-based value (assuming ~100ms cycle time) rTimeSeconds := UINT_TO_REAL(uiSeqCounter) * 0.1; // Approximate time in seconds
(* ---------------------------------------------------------------------- METRIC 0: Protocol Version (Static) ---------------------------------------------------------------------- *) typPayloadOut.atypMetrics[0].sName := 'Version'; typPayloadOut.atypMetrics[0].rValue := 42.64; // Static protocol version typPayloadOut.atypMetrics[0].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 1: GPS Latitude (Sinusoidal Wave - Simulates North/South drift) ---------------------------------------------------------------------- *) // Base: 43.20123° + amplitude ±0.001° with 60-second period typPayloadOut.atypMetrics[1].sName := 'GPS.Latitude'; typPayloadOut.atypMetrics[1].rValue := 43.20123 + 0.001 * SIN(rTimeSeconds * 0.1047); // 2π/60 typPayloadOut.atypMetrics[1].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 2: Engine Power (Cosine + Sawtooth - Simulates Load Variation) ---------------------------------------------------------------------- *) // Base: 1850 kW with ±150 kW cosine variation + 50 kW sawtooth typPayloadOut.atypMetrics[2].sName := 'Engine.Power_kW'; typPayloadOut.atypMetrics[2].rValue := 1850.0 + 150.0 * COS(rTimeSeconds * 0.0628) + // 2π/100 50.0 * (TO_INT(rTimeSeconds) MOD 10) / 10.0; // Sawtooth 0-10s typPayloadOut.atypMetrics[2].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 3: GPS Longitude (Cosine Wave - Simulates East/West drift) ---------------------------------------------------------------------- *) // Base: 7.31234° + amplitude ±0.0015° with 80-second period (phase shifted) typPayloadOut.atypMetrics[3].sName := 'GPS.Longitude'; typPayloadOut.atypMetrics[3].rValue := 7.31234 + 0.0015 * COS(rTimeSeconds * 0.0785 + 1.57); // π/2 phase shift typPayloadOut.atypMetrics[3].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 4: Engine RPM (Triangle Wave - Simulates Throttle Changes) ---------------------------------------------------------------------- *) // Triangle wave between 1200-2400 RPM with 20-second period typPayloadOut.atypMetrics[4].sName := 'Engine.RPM'; IF (UINT_TO_REAL(uiSeqCounter MOD 200) < 100.0) THEN // Rising edge: 1200 -> 2400 typPayloadOut.atypMetrics[4].rValue := 1200.0 + 1200.0 * UINT_TO_REAL(uiSeqCounter MOD 100) / 100.0; ELSE // Falling edge: 2400 -> 1200 typPayloadOut.atypMetrics[4].rValue := 2400.0 - 1200.0 * UINT_TO_REAL(uiSeqCounter MOD 100) / 100.0; END_IF; typPayloadOut.atypMetrics[4].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 5: Battery State of Charge (Exponential Decay + Sine Ripple) ---------------------------------------------------------------------- *) // Slow discharge from 100% to 75% with ±2% charging ripple typPayloadOut.atypMetrics[5].sName := 'Battery.StateOfCharge'; typPayloadOut.atypMetrics[5].rValue := 100.0 - (rTimeSeconds * 0.01) + // Slow discharge 1%/100s 2.0 * SIN(rTimeSeconds * 0.314); // Fast ripple 2π/20 // Clamp between 75-100% IF typPayloadOut.atypMetrics[5].rValue < 75.0 THEN typPayloadOut.atypMetrics[5].rValue := 75.0; ELSIF typPayloadOut.atypMetrics[5].rValue > 100.0 THEN typPayloadOut.atypMetrics[5].rValue := 100.0; END_IF; typPayloadOut.atypMetrics[5].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 6: Shore Power Connection (Pseudo-Random Toggle) ---------------------------------------------------------------------- *) // Simulates intermittent shore power connection using sequence-based toggle typPayloadOut.atypMetrics[6].sName := 'ShorePower.Connected'; // Toggle every ~50 counts with pseudo-random behavior typPayloadOut.atypMetrics[6].rValue := BOOL_TO_REAL((uiSeqCounter MOD 47) < 23); // ~50% duty typPayloadOut.atypMetrics[6].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 7: Water Temperature (Slow Sine + Fast Noise) ---------------------------------------------------------------------- *) // Base: 18.5°C with ±2°C daily variation + ±0.3°C sensor noise typPayloadOut.atypMetrics[7].sName := 'Sensors.WaterTemp_C';
// Pseudo-random noise using sequence counter hash rNoiseAccum := UINT_TO_REAL((uiSeqCounter * 127 + 31) MOD 100) / 100.0 - 0.5; // Range: -0.5 to 0.5
typPayloadOut.atypMetrics[7].rValue := 18.5 + 2.0 * SIN(rTimeSeconds * 0.000727) + // 24-hour period 0.3 * rNoiseAccum; // Sensor noise ±0.3°C typPayloadOut.atypMetrics[7].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 8: Wind Speed (Gusty Wind Simulation - Multiple Harmonics) ---------------------------------------------------------------------- *) // Base wind + slow variation + fast gusts typPayloadOut.atypMetrics[8].sName := 'Weather.WindSpeed_kts'; typPayloadOut.atypMetrics[8].rValue := 12.0 + // Base: 12 knots 5.0 * SIN(rTimeSeconds * 0.0314) + // Slow variation: 200s period 2.0 * COS(rTimeSeconds * 0.628) + // Fast gusts: 10s period 1.0 * SIN(rTimeSeconds * 1.257); // Turbulence: 5s period // Clamp to realistic values (0-30 knots) IF typPayloadOut.atypMetrics[8].rValue < 0.0 THEN typPayloadOut.atypMetrics[8].rValue := 0.0; ELSIF typPayloadOut.atypMetrics[8].rValue > 30.0 THEN typPayloadOut.atypMetrics[8].rValue := 30.0; END_IF; typPayloadOut.atypMetrics[8].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- METRIC 9: Fuel Level (Linear Decay with Step Changes) ---------------------------------------------------------------------- *) // Simulates fuel consumption with occasional refueling typPayloadOut.atypMetrics[9].sName := 'Fuel.Level_Liters';
// Linear decay: 5000L -> 1000L over 400 counts, then reset IF (uiSeqCounter MOD 400) = 0 THEN typPayloadOut.atypMetrics[9].rValue := 5000.0; // Refuel event ELSE typPayloadOut.atypMetrics[9].rValue := 5000.0 - (10.0 * UINT_TO_REAL(uiSeqCounter MOD 400)); END_IF; typPayloadOut.atypMetrics[9].usiTypeID := 9; // REAL type
(* ---------------------------------------------------------------------- Set Active Metric Count ---------------------------------------------------------------------- *) typPayloadOut.usiMetricCnt := 10; // Updated to include all new metrics
END_IF
(* ============================================================================ Waveform Summary: - Metric 1: SIN (smooth oscillation - GPS Latitude) - Metric 2: COS + Sawtooth (periodic + ramp - Engine Power) - Metric 3: COS with phase shift (offset oscillation - GPS Longitude) - Metric 4: Triangle wave (symmetric ramp - Engine RPM) - Metric 5: Linear + SIN (decay + ripple - Battery SoC) - Metric 6: Pseudo-random toggle (binary state - Shore Power) - Metric 7: SIN + noise (slow + fast - Water Temperature) - Metric 8: Multi-harmonic (complex wind simulation - Wind Speed) - Metric 9: Step function (discrete events - Fuel Level) ============================================================================ *)

uiPRNG := uiPRNG * 1664525 + 1013904223;   // LCG
tmp := uiPRNG AND 16#7FFFFFFF;
FuPRNG := TO_REAL(tmp) / TO_REAL(16#7FFFFFFF);     // 0..1

(* ============================================================================
   MAIN LOGIC
   ============================================================================ *)

IF NOT xEnable THEN
    bValid := FALSE;
    RETURN;
END_IF

(* ----------------------------------------------------------------------------
   Initialize metric configurations on first run
   ---------------------------------------------------------------------------- *)
IF NOT xInitialized THEN
    FOR i := 0 TO 141 DO
        arMetricMin[i] := 0.0;
        arMetricMax[i] := 100.0;
        arMetricCenter[i] := 50.0;
        arMetricAmplitude[i] := 25.0;
        aiWaveformType[i] := 0;
        arPhaseOffset[i] := TO_REAL(i) * 0.1;
        arFreqMultiplier[i] := 1.0;
        axAnomalyFreezeActive[i] := FALSE;
        arAnomalyFreezeValue[i] := 0.0;
    END_FOR

    (* === Configure yacht telemetry metrics === *)

    (* Index 0: timestamp *)
    aMetricNames[0] := 'timestamp';
    arMetricMin[0] := 0.0; arMetricMax[0] := 999999999.0;
    arMetricCenter[0] := 0.0; arMetricAmplitude[0] := 0.0;
    aiWaveformType[0] := 3;

    (* Index 1: seq *)
    aMetricNames[1] := 'seq';
    arMetricMin[1] := 0.0; arMetricMax[1] := 999999.0;
    arMetricCenter[1] := 0.0; arMetricAmplitude[1] := 0.0;
    aiWaveformType[1] := 3;

    (* Index 2-11: Engine metrics *)
    aMetricNames[2] := 'engine_rpm_port';
    arMetricMin[2] := 0.0; arMetricMax[2] := 3500.0;
    arMetricCenter[2] := 1800.0; arMetricAmplitude[2] := 500.0;
    aiWaveformType[2] := 0; arFreqMultiplier[2] := 0.3;

    aMetricNames[3] := 'engine_rpm_starboard';
    arMetricMin[3] := 0.0; arMetricMax[3] := 3500.0;
    arMetricCenter[3] := 1800.0; arMetricAmplitude[3] := 500.0;
    aiWaveformType[3] := 0; arFreqMultiplier[3] := 0.31; arPhaseOffset[3] := 0.1;

    aMetricNames[4] := 'engine_temp_port';
    arMetricMin[4] := 60.0; arMetricMax[4] := 110.0;
    arMetricCenter[4] := 85.0; arMetricAmplitude[4] := 10.0;
    aiWaveformType[4] := 0; arFreqMultiplier[4] := 0.1;

    aMetricNames[5] := 'engine_temp_starboard';
    arMetricMin[5] := 60.0; arMetricMax[5] := 110.0;
    arMetricCenter[5] := 85.0; arMetricAmplitude[5] := 10.0;
    aiWaveformType[5] := 0; arFreqMultiplier[5] := 0.11; arPhaseOffset[5] := 0.2;

    aMetricNames[6] := 'engine_oil_pressure_port';
    arMetricMin[6] := 20.0; arMetricMax[6] := 80.0;
    arMetricCenter[6] := 50.0; arMetricAmplitude[6] := 15.0;
    aiWaveformType[6] := 0; arFreqMultiplier[6] := 0.2;

    aMetricNames[7] := 'engine_oil_pressure_starboard';
    arMetricMin[7] := 20.0; arMetricMax[7] := 80.0;
    arMetricCenter[7] := 50.0; arMetricAmplitude[7] := 15.0;
    aiWaveformType[7] := 0; arFreqMultiplier[7] := 0.21; arPhaseOffset[7] := 0.15;

    aMetricNames[8] := 'engine_load_port';
    arMetricMin[8] := 0.0; arMetricMax[8] := 100.0;
    arMetricCenter[8] := 60.0; arMetricAmplitude[8] := 30.0;
    aiWaveformType[8] := 0; arFreqMultiplier[8] := 0.15;

    aMetricNames[9] := 'engine_load_starboard';
    arMetricMin[9] := 0.0; arMetricMax[9] := 100.0;
    arMetricCenter[9] := 60.0; arMetricAmplitude[9] := 30.0;
    aiWaveformType[9] := 0; arFreqMultiplier[9] := 0.16; arPhaseOffset[9] := 0.1;

    aMetricNames[10] := 'engine_coolant_level_port';
    arMetricMin[10] := 0.0; arMetricMax[10] := 100.0;
    arMetricCenter[10] := 95.0; arMetricAmplitude[10] := 3.0;
    aiWaveformType[10] := 2; arFreqMultiplier[10] := 0.05;

    aMetricNames[11] := 'engine_coolant_level_starboard';
    arMetricMin[11] := 0.0; arMetricMax[11] := 100.0;
    arMetricCenter[11] := 95.0; arMetricAmplitude[11] := 3.0;
    aiWaveformType[11] := 2; arFreqMultiplier[11] := 0.05; arPhaseOffset[11] := 0.5;

    (* Index 12-15: Generator *)
    aMetricNames[12] := 'generator_rpm';
    arMetricMin[12] := 0.0; arMetricMax[12] := 1800.0;
    arMetricCenter[12] := 1500.0; arMetricAmplitude[12] := 50.0;
    aiWaveformType[12] := 0; arFreqMultiplier[12] := 0.5;

    aMetricNames[13] := 'generator_load';
    arMetricMin[13] := 0.0; arMetricMax[13] := 100.0;
    arMetricCenter[13] := 45.0; arMetricAmplitude[13] := 25.0;
    aiWaveformType[13] := 2; arFreqMultiplier[13] := 0.2;

    aMetricNames[14] := 'generator_oil_pressure';
    arMetricMin[14] := 20.0; arMetricMax[14] := 60.0;
    arMetricCenter[14] := 40.0; arMetricAmplitude[14] := 10.0;
    aiWaveformType[14] := 0; arFreqMultiplier[14] := 0.1;

    aMetricNames[15] := 'generator_temp';
    arMetricMin[15] := 50.0; arMetricMax[15] := 100.0;
